import { SeedTsCustomHeaderAuthRedactionClient } from "@fern/ts-custom-header-auth-redaction";

const client = new SeedTsCustomHeaderAuthRedactionClient({ baseUrl: "YOUR_BASE_URL", secret: "YOUR_SECRET", clientId: "YOUR_CLIENT_ID", version: "YOUR_VERSION" });
